static constexpr uint16_t LIMIT=6000;struct ImportRow{uint8_t z;uint32_t x,y;};
static lv_obj_t *page,*centreLabel,*estimateLabel,*packLabel,*coverageLabel,*progress,*importLabel,*importBtn;static lv_obj_t*zoomLabels[6];static float lat=43,lon=25;static bool chosen[6]={true,true,true,true,false,false};static uint8_t zlist[6]={14,15,16,17,18,19};static MapManagerReturnCallback onBack;
static ImportRow *importRows=nullptr;static uint16_t importCount=0,importIndex=0;static bool importing=false;static uint8_t importStyle=0;static File inFile,outFile;static uint8_t copyPhase=0;static const char*copyFiles[2]={"/map-import/coverage_index.csv","/map-import/manifest.txt"};static uint32_t copied=0,totalBytes=0;
static lv_obj_t*label(lv_obj_t*p,const char*t,int x,int y,int w=750){lv_obj_t*l=lv_label_create(p);lv_label_set_text(l,t);lv_obj_set_pos(l,x,y);lv_obj_set_width(l,w);lv_label_set_long_mode(l,LV_LABEL_LONG_WRAP);return l;}
static void refresh(){char s[180];snprintf(s,sizeof(s),"Centre %.6f, %.6f | 1 km square",lat,lon);lv_label_set_text(centreLabel,s);uint8_t zs[6],n=0;uint32_t tiles=0;double dlat=500/111320.0,co=fabs(cos(lat*M_PI/180));if(co<1e-5)co=1e-5;double dlon=500/(111320.0*co);for(int i=0;i<6;i++){char z[12];snprintf(z,sizeof(z),"Z%u%s",zlist[i],chosen[i]?" *":"");lv_label_set_text(zoomLabels[i],z);if(chosen[i]){zs[n++]=zlist[i];double nn=1UL<<zlist[i];int x0=floor((lon-dlon+180)/360*nn),x1=floor((lon+dlon+180)/360*nn);double north=lat+dlat,south=lat-dlat;int y0=floor((1-asinh(tan(north*M_PI/180))/M_PI)/2*nn),y1=floor((1-asinh(tan(south*M_PI/180))/M_PI)/2*nn);tiles+=(x1-x0+1)*(abs(y1-y0)+1);}}
uint32_t bytes=tiles*131072UL;snprintf(s,sizeof(s),"Estimate ~%lu tiles | %.2f MiB raw | %.2f MiB +10%%",(unsigned long)tiles,bytes/1048576.0,bytes*1.1/1048576.0);lv_label_set_text(estimateLabel,s);uint16_t total=0,ok=0,missing=0;offlineMap_getCoverageStats(total,ok,missing);snprintf(s,sizeof(s),"Active pack: %s | %u indexed / %u present / %u missing",offlineMap_hasMapData()?"VALID":"NONE",total,ok,missing);lv_label_set_text(packLabel,s);uint16_t need=0,covered=0,miss=0;mapCoverage_checkSquare(lat,lon,1000,zs,n,need,covered,miss);snprintf(s,sizeof(s),"Area coverage: %u/%u tiles | %u missing",covered,need,miss);lv_label_set_text(coverageLabel,s);lv_bar_set_value(progress,need?covered*100/need:0,LV_ANIM_OFF);}
static void nLat(int d){lat=fmax(-85.0f,fmin(85.0f,lat+d*.001f));refresh();}static void nLon(int d){lon+=d*.001f;if(lon>180)lon-=360;if(lon< -180)lon+=360;refresh();}
static void zoomToggle(lv_event_t*e){int i=(intptr_t)lv_event_get_user_data(e);chosen[i]=!chosen[i];refresh();}
static bool copyStart(const char*src,const char*dst){inFile=SD.open(src,FILE_READ);if(!inFile)return false;char dir[100];strncpy(dir,dst,sizeof(dir)-1);dir[sizeof(dir)-1]=0;char*last=strrchr(dir,'/');if(last){*last=0;SD.mkdir(dir);}outFile=SD.open(dst,FILE_WRITE);if(!outFile){inFile.close();return false;}return true;}
static bool copyChunk(){if(!inFile||!outFile)return false;uint8_t buf[4096];size_t n=inFile.read(buf,sizeof(buf));if(n){if(outFile.write(buf,n)!=n){inFile.close();outFile.close();return false;}copied+=n;}if(!inFile.available()){inFile.close();outFile.close();return true;}return false;}
static void importStart(lv_event_t*e){if(importing||!SD.exists("/map-import/manifest.txt")||!SD.exists("/map-import/coverage_index.csv")){lv_label_set_text(importLabel,"No staged pack at /map-import/");return;}File m=SD.open("/map-import/manifest.txt",FILE_READ);char text[512]={};m.readBytes(text,sizeof(text)-1);m.close();if(!strstr(text,"pack_complete=true")||!strstr(text,"attribution=")||!strstr(text,"licence_url=")||!strstr(text,"zoom_levels=")){lv_label_set_text(importLabel,"Staged manifest rejected: incomplete or missing licence metadata");return;}if(strstr(text,"style=street"))importStyle=0;else if(strstr(text,"style=satellite"))importStyle=1;else{lv_label_set_text(importLabel,"Staged pack must declare style=street or satellite");return;}if(importRows)heap_caps_free(importRows);importRows=(ImportRow*)heap_caps_malloc(sizeof(ImportRow)*LIMIT,MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT);if(!importRows){lv_label_set_text(importLabel,"PSRAM allocation failed");return;}File idx=SD.open("/map-import/coverage_index.csv",FILE_READ);char line[48];bool header=false;importCount=0;while(idx.available()){size_t n=idx.readBytesUntil('\n',line,sizeof(line)-1);line[n]=0;if(!n)continue;if(!header){header=true;if(strcmp(line,"z,x,y,present"))break;continue;}if(importCount>=LIMIT)break;char*a=strtok(line,",");char*b=strtok(nullptr,",");char*c=strtok(nullptr,",");char*d=strtok(nullptr,",");if(!a||!b||!c||!d||atoi(d)!=1)break;int z=atoi(a);uint32_t x=strtoul(b,nullptr,10),y=strtoul(c,nullptr,10);if(z<0||z>22||x>=(1UL<<z)||y>=(1UL<<z))break;importRows[importCount++]={(uint8_t)z,x,y};}idx.close();if(!header||!importCount){lv_label_set_text(importLabel,"Coverage index invalid/empty or incomplete");return;}File ixSize=SD.open("/map-import/coverage_index.csv",FILE_READ);uint32_t ixBytes=ixSize?ixSize.size():0;if(ixSize)ixSize.close();File mSize=SD.open("/map-import/manifest.txt",FILE_READ);uint32_t mBytes=mSize?mSize.size():0;if(mSize)mSize.close();importIndex=0;copyPhase=0;copied=0;totalBytes=(uint32_t)importCount*OFFLINE_MAP_TILE_BYTES+ixBytes+mBytes;SD.remove("/maps/manifest.txt");importing=true;lv_label_set_text(importLabel,"Import started — copying staged tiles to active map folder");}
static void back(lv_event_t*e){if(lv_event_get_code(e)==LV_EVENT_CLICKED&&!importing){lv_obj_del(page);if(onBack)onBack();}}
static void button(lv_obj_t*p,const char*t,int x,int y,int w,lv_event_cb_t cb,void*ud=nullptr){lv_obj_t*b=lv_button_create(p);lv_obj_set_size(b,w,38);lv_obj_set_pos(b,x,y);lv_label_set_text(lv_label_create(b),t);lv_obj_center(lv_obj_get_child(b,0));lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,ud);}
void mapManagerUI_open(lv_obj_t*parent,float gpsLat,float gpsLon,bool gpsValid,MapManagerReturnCallback cb){onBack=cb;lat=gpsValid?gpsLat:43;lon=gpsValid?gpsLon:25;page=lv_obj_create(parent);lv_obj_set_size(page,790,440);lv_obj_center(page);lv_obj_set_style_bg_color(page,lv_color_hex(0x101820),LV_PART_MAIN);lv_obj_set_style_pad_all(page,10,LV_PART_MAIN);label(page,"OFFLINE MAP MANAGER",8,4,400);centreLabel=label(page,"",8,38);label(page,"Coordinate nudges ±0.001° (~111m lat)",8,70);button(page,"LAT +",8,100,80,[](lv_event_t*){nLat(1);});button(page,"LAT -",94,100,80,[](lv_event_t*){nLat(-1);});button(page,"LON -",180,100,80,[](lv_event_t*){nLon(-1);});button(page,"LON +",266,100,80,[](lv_event_t*){nLon(1);});button(page,"USE GPS",354,100,130,[](lv_event_t*){if(boatState.gpsValid){lat=boatState.latitude;lon=boatState.longitude;refresh();}});label(page,"Zoom (toggle)",8,151);for(int i=0;i<6;i++){lv_obj_t*b=lv_button_create(page);lv_obj_set_size(b,72,40);lv_obj_set_pos(b,8+i*80,176);zoomLabels[i]=lv_label_create(b);lv_obj_center(zoomLabels[i]);lv_obj_add_event_cb(b,zoomToggle,LV_EVENT_CLICKED,(void*)(intptr_t)i);}estimateLabel=label(page,"Estimate",8,230);packLabel=label(page,"Pack status",8,267);coverageLabel=label(page,"Coverage",8,304);progress=lv_bar_create(page);lv_obj_set_size(progress,760,20);lv_obj_set_pos(progress,8,337);lv_bar_set_range(progress,0,100);importLabel=label(page,"Import status: stage a licensed complete pack under /map-import/",8,361);importBtn=lv_button_create(page);lv_obj_set_size(importBtn,180,38);lv_obj_set_pos(importBtn,8,390);lv_label_set_text(lv_label_create(importBtn),"IMPORT STAGED PACK");lv_obj_center(lv_obj_get_child(importBtn,0));lv_obj_add_event_cb(importBtn,importStart,LV_EVENT_CLICKED,nullptr);button(page,"BACK",665,390,100,back);refresh();}
void mapManagerUI_tick(){static uint32_t lastTick=0;if(!importing||millis()-lastTick<25)return;lastTick=millis();char src[100],dst[100];if(importIndex<importCount){ImportRow r=importRows[importIndex];const char*style=importStyle?"satellite":"street";snprintf(src,sizeof(src),"/map-import/%s/%u/%lu/%lu.rgb565",style,r.z,(unsigned long)r.x,(unsigned long)r.y);snprintf(dst,sizeof(dst),"/maps/%s/%u/%lu/%lu.rgb565",style,r.z,(unsigned long)r.x,(unsigned long)r.y);if(!inFile){if(!copyStart(src,dst)){importing=false;lv_label_set_text(importLabel,"Import failed: tile missing or SD write/open error");return;}}bool done=copyChunk();if(!outFile&&!inFile&&done)importIndex++;}else{if(copyPhase<2){const char*srcPath=copyFiles[copyPhase];const char*dstPath=copyPhase==0?"/maps/coverage_index.csv":"/maps/manifest.txt";if(!inFile){if(!copyStart(srcPath,dstPath)){importing=false;lv_label_set_text(importLabel,"Import failed copying index/manifest");return;}}bool done=copyChunk();if(!outFile&&!inFile&&done)copyPhase++;}else{importing=false;boatState.offlineMapReady=offlineMap_begin(true);lv_label_set_text(importLabel,boatState.offlineMapReady?"Import complete — pack validated":"Import complete but pack validation failed");refresh();}}
char status[100];snprintf(status,sizeof(status),"Import %u/%u tiles | %lu/%lu bytes",(unsigned)importIndex,(unsigned)importCount,(unsigned long)copied,(unsigned long)totalBytes);lv_label_set_text(importLabel,status);lv_bar_set_value(progress,totalBytes?copied*100/totalBytes:0,LV_ANIM_OFF);}
